---@class RewardSelectCardNode
---@field Card                          	UnityEngine.RectTransform
---@field TxtCardName                   	UnityEngine.UI.Text
---@field ImgCardHead                   	Engine.UI.ImageAlterable
---@field SelectedBg                    	UnityEngine.RectTransform
local RewardSelectCardNode = Class("RewardSelectCardNode")
function RewardSelectCardNode:__init()
    self.btnActionGet = nil
    self.btnAction = nil
    self.canGet = false
end

function RewardSelectCardNode:__delete()
    self.btnActionGet = nil
    self.btnAction = nil
    self.canGet = nil

    self.controller = nil
end

---SetBtnCallBackGet
---设置单击回调函数(领取)
function RewardSelectCardNode:SetBtnCallBackGet(cb)
    self.btnActionGet = cb
end

---SetCallBack
---设置单击回调函数
function RewardSelectCardNode:SetBtnCallBack(cb)
    self.btnAction = cb
end

function RewardSelectCardNode:Awake()
    SetButtonAction(self.Card, function ()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end)
    SetButtonAction(self.FontStyleButton, function()--领取
        if type(self.btnActionGet) == 'function' then
            if self.canGet then
                self.btnActionGet()
            else
                if self.isGet then
                    GameUtils.Toast(localize("奖励已领取"))
                else
                    GameUtils.Toast(localize("未达成"))
                end
            end
        end
    end)
end

--是否可领取
function RewardSelectCardNode:SetGetStatus(isAchieve, isGet)
    isAchieve = checkBool(isAchieve)
    isGet = checkBool(isGet)
    self.isAchieve = isAchieve
    self.isGet = isGet
    self.canGet = isAchieve and (not isGet)
end

function RewardSelectCardNode:FreshBaseUI(data)
    local cardVo = CardConfMgr:GetInstance():GetCardDefaultSkinByCardId(data.reward)
    if not self.canGet then
        self.FontStyleButton:GetComponent("FontStyleButton"):ResetFontStyle("B22")
    end
    self.ImgCardHead:LoadSprite(cardVo.cardHeadList)
    self.TxtCardName.text = cardVo.name
    SetButtonAction(self.CardNameLabel.parent, function ()
        GachaponUtils.OpenDetail(data.reward)
    end)
end

function RewardSelectCardNode:FreshSelectStatus(isSelected)
    KTool.SetActive(self.SelectedBg, isSelected)
    KTool.SetActive(self.FontStyleButton, isSelected)
end

function RewardSelectCardNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return RewardSelectCardNode